def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    opp_def = sum(1 for a in opp if a == 'D')
    me_def = sum(1 for a in me if a == 'D')
    last_me, last_opp = history[-1]

    # Endgame: defect in final rounds
    if n >= 98:
        return 'D'

    # Count consecutive opponent defections at the tail
    cons_opp_d = 0
    for a in reversed(opp):
        if a == 'D':
            cons_opp_d += 1
        else:
            break

    # If opponent opens with defections (probe they defected early), respond firmly
    # but be willing to recover if they switch back to cooperation.
    if n <= 6:
        if opp_def == 0:
            return 'C'
        if last_opp == 'D':
            # Immediate retaliation once, then re-evaluate
            if cons_opp_d >= 2:
                return 'D'
            return 'D'
        return 'C'

    # Very recent window
    recent = opp[-8:] if n >= 8 else opp
    recent_def = sum(1 for a in recent if a == 'D')
    rlen = len(recent)

    # Detect overwhelmingly cooperative opponent -> keep cooperating (avoid
    # triggering retaliation that could cost us long mutual C runs).
    if opp_def == 0:
        return 'C'

    # If we ourselves have defected but opponent still cooperates, repair by C
    if me_def > 0 and opp_def == 0:
        return 'C'

    # Heavy recent defection: retaliate firmly
    if rlen >= 4 and recent_def * 2 >= rlen:
        if recent_def == rlen:
            return 'D'
        # Opponent shows some cooperation in window: probe an olive branch
        if last_opp == 'C' and rng.random() < 0.4:
            return 'C'
        return 'D'

    # Sustained defector detection
    if opp_def >= 6 and opp_def * 2 > n:
        return 'D'

    # Respond to last opponent move
    if last_opp == 'D':
        # Long defection streak: don't give free points
        if cons_opp_d >= 4:
            return 'D'
        if cons_opp_d >= 2:
            # Rare olive branch after short streaks
            if rng.random() < 0.2:
                return 'C'
            return 'D'
        # Single defection after cooperation: retaliate once, but forgive often
        # so a TFT-like opponent can return to mutual C quickly.
        if rng.random() < 0.45:
            return 'C'
        return 'D'

    # last_opp == 'C'
    # Cooperate, but avoid being an easy exploiter against periodic defectors.
    # If they have some history of defection and we've been very cooperative,
    # occasionally pre-empt.
    if opp_def > 0 and n >= 10:
        # If opponent's defections are sparse, still mostly cooperate
        if opp_def * 4 < n:
            return 'C'
        # More defections: mix in occasional pre-emptive D
        if rng.random() < 0.15:
            return 'D'
        return 'C'

    return 'C'
